#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 998244353
#define MAXN 200005

typedef struct {
    int to, next;
} Edge;

Edge edges[2 * MAXN];
int head[MAXN], eidx;
int n;

void add_edge(int u, int v) {
    edges[eidx].to = v;
    edges[eidx].next = head[u];
    head[u] = eidx++;
}

int dist[MAXN], parent[MAXN];
int q[MAXN];

void bfs(int s) {
    memset(dist, -1, sizeof(dist));
    int front = 0, back = 0;
    dist[s] = 0;
    parent[s] = 0;
    q[back++] = s;
    while (front < back) {
        int u = q[front++];
        for (int i = head[u]; i != -1; i = edges[i].next) {
            int v = edges[i].to;
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q[back++] = v;
            }
        }
    }
}

