public class Main {
    static final int MOD = 998244353;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        List<Integer>[] g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();
        for (int i = 0; i < N - 1; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken()) - 1;
            int b = Integer.parseInt(st.nextToken()) - 1;
            g[a].add(b);
            g[b].add(a);
        }

        // Find diameter path
        int[] dist1 = bfs(0, g);
        int u = 0;
        for (int i = 0; i < N; i++) if (dist1[i] > dist1[u]) u = i;
        int[] distU = bfs(u, g);
        int v = 0;
        for (int i = 0; i < N; i++) if (distU[i] > distU[v]) v = i;
        int[] distV = bfs(v, g);
        int diam = distU[v];

        // Find center(s)
        List<Integer> centers = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            if (distU[i] + distV[i] == diam && Math.abs(distU[i] - distV[i]) <= 1) {
                centers.add(i);
            }
        }

        if (centers.size() == 1) {
            int c = centers.get(0);
            int r = diam / 2;
            List<Integer>[] levels = new ArrayList[r + 1];
            for (int i = 0; i <= r; i++) levels[i] = new ArrayList<>();
            dfs(c, -1, 0, g, levels);
            long ans = 1;
            for (int d = 0; d <= r; d++) {
                if (levels[d].isEmpty()) continue;
                int sz = levels[d].size();
                // number of edges we can add = sz * (sz - 1) / 2
                long add = 1;
                long pairs = (long) sz * (sz - 1) / 2 % MOD;
                // each edge can be added or not
                add = pow2(pairs);
                ans = ans * add % MOD;
            }
            System.out.println(ans);
        } else {
            int c1 = centers.get(0), c2 = centers.get(1);
            int r = diam / 2;
            List<Integer>[] levels1 = new ArrayList[r + 1];
            List<Integer>[] levels2 = new ArrayList[r + 1];
            for (int i = 0; i <= r; i++) { levels1[i] = new ArrayList<>(); levels2[i] = new ArrayList<>(); }
            dfs(c1, c2, 0, g, levels1);
            dfs(c2, c1, 0, g, levels2);
            long ans = 1;
            for (int d = 0; d <= r; d++) {
                int sz1 = levels1[d].size();
                int sz2 = levels2[d].size();
                long pairs = (long) sz1 * sz2 % MOD;
                ans = ans * pow2(pairs) % MOD;
            }
            System.out.println(ans);
        }
    }

    static int[] bfs(int start, List<Integer>[] g) {
        int n = g.length;
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        Queue<Integer> q = new LinkedList<>();
        q.add(start);
        dist[start] = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                }
            }
        }
        return dist;
    }

    static void dfs(int u, int p, int d, List<Integer>[] g, List<Integer>[] levels) {
        levels[d].add(u);
        for (int v : g[u]) {
            if (v != p) {
                dfs(v, u, d + 1, g, levels);
            }
        }
    }

    static long pow2(long e) {
        long res = 1, base = 2;
        while (e > 0) {
            if ((e & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            e >>= 1;
        }
        return res;
    }
}

