        }

        int k = (D - 1) / 2;
        int c1 = path.get(k);
        int c2 = path.get(k + 1);

        long[] A = countDepths(c1, c2, k, g);
        long[] B = countDepths(c2, c1, k, g);

        long ans = 1;
        for (int i = 0; i <= k; i++) {
