    static long[] countDepths(int start, int blocked, int maxDepth, List<Integer>[] g) {
        long[] cnt = new long[maxDepth + 1];
        int n = g.length;
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        dist[start] = 0;
        q.add(start);
        while (!q.isEmpty()) {
            int v = q.poll();
            if (dist[v] <= maxDepth) cnt[dist[v]]++;
            if (dist[v] == maxDepth) continue;
            for (int to : g[v]) {
                if (v == start && to == blocked) continue;
                if (dist[to] != -1) continue;
                dist[to] = dist[v] + 1;
                q.add(to);
            }
        }
        return cnt;
    }

    static class BFSRes {
        int node;
        int[] dist;
        int[] parent;
        BFSRes(int node, int[] dist, int[] parent) {
            this.node = node;
            this.dist = dist;
            this.parent = parent;
        }
    }

    static BFSRes bfsFarthest(int src, List<Integer>[] g, Integer blockedNeighborFromSrc) {
        int n = g.length;
        int[] dist = new int[n];
        int[] parent = new int[n];
        Arrays.fill(dist, -1);
        Arrays.fill(parent, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        dist[src] = 0;
        q.add(src);
        int far = src;
        while (!q.isEmpty()) {
            int v = q.poll();
            if (dist[v] > dist[far]) far = v;
            for (int to : g[v]) {
                if (v == src && blockedNeighborFromSrc != null && to == blockedNeighborFromSrc) continue;
                if (dist[to] != -1) continue;
                dist[to] = dist[v] + 1;
                parent[to] = v;
                q.add(to);
            }
        }
        return new BFSRes(far, dist, parent);
    }

    static long modPow(long a, long e, long mod) {
        long r = 1 % mod;
        a %= mod;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % mod;
            a = a * a % mod;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
