#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353LL;

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

vector<int> bfs_dist(int s, const vector<vector<int>>& g) {
    int n = (int)g.size() - 1;
    vector<int> dist(n + 1, -1);
    queue<int> q;
    dist[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int to : g[v]) {
            if (dist[to] == -1) {
                dist[to] = dist[v] + 1;
                q.push(to);
            }
        }
    }
    return dist;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<vector<int>> g(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    if (N == 1) {
        cout << 1 << '\n';
        return 0;
    }

    // Find tree diameter endpoints s, t
    auto d1 = bfs_dist(1, g);
    int s = 1;
    for (int i = 1; i <= N; ++i) if (d1[i] > d1[s]) s = i;

    auto ds = bfs_dist(s, g);
    int t = s;
    for (int i = 1; i <= N; ++i) if (ds[i] > ds[t]) t = i;

    auto dt = bfs_dist(t, g);
    int D = ds[t];

    // Characterization:
    // Let S be the set of vertices lying on some diameter path, i.e. ds[v] + dt[v] == D.
    // In any valid H:
    // - all pairs inside S must be edges (otherwise adding one may not reduce diameter)
    // - no edge can connect two vertices outside S, because then diameter would drop below D
    // - every edge between S and outside S can be chosen independently
    //
    // Number = 2^( |S| * (N-|S|) ) if D>=2, with special handling naturally included.
    //
    // Why no outside-outside edge:
    // For u,v outside S, eccentricity in tree is < D. Adding uv cannot create a pair at distance > D,
    // and in fact all diameter pairs lie in S, so diameter in H would become < D if we also satisfy maximality.
    //
    // More directly, the valid graphs are exactly the edge-maximal supergraphs of G with diameter D,
    // and those are obtained by making S a clique and freely choosing edges between S and V\S.

    int cntS = 0;
    for (int v = 1; v <= N; ++v) {
        if (ds[v] + dt[v] == D) cntS++;
    }

    long long exponent = 1LL * cntS * (N - cntS);
    cout << modpow(2, exponent) << '\n';
    return 0;
}
